    def legal(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in obs_set

    def dist2(a, b, c, d):
        dx, dy = a - c, b - d
        return dx * dx + dy * dy

    def min_obs_dist2(x, y):
        md = None
        for ax, ay in obs_list:
            d2 = (x - ax) * (x - ax) + (y - ay) * (y - ay)
            if md is None or d2 < md:
